#DATA ANALYTICS FINAL PROJECT- SQL

#Top 5 Overall: Identifies the five highest-scoring students across all departments using RANK().
#Top 5 Per Department: Finds the top five score ranks within each department using DENSE_RANK() and a CTE.
#Academic Status: Compares each student's score with their department average and classifies them as Above Average, Below Average, or Same as Average.
#Highest & Lowest Scores: Finds the maximum and minimum score in each department using MAX() and MIN().
#Score Gap: Uses LAG() to calculate the score difference between a student and the next higher-scoring student within the same department.
#Stored Procedure: Retrieves the lifestyle details of a particular student by providing their student_id.
create database final_project;
use final_project;
create table students(
    student_id VARCHAR(20) PRIMARY KEY,
    first_name VARCHAR(50),
    last_name VARCHAR(50),
    email VARCHAR(100),
    gender VARCHAR(20),
    age INT,
    department VARCHAR(50)
);
CREATE TABLE academic_performance(
    student_id VARCHAR(20) PRIMARY KEY,
    attendance_pct DECIMAL(5,2),
    midterm_score DECIMAL(5,2),
    final_score DECIMAL(5,2),
    assignments_avg DECIMAL(5,2),
    quizzes_avg DECIMAL(5,2),
    participation_score DECIMAL(5,2),
    projects_score DECIMAL(5,2),
    total_score DECIMAL(6,4),
    grade VARCHAR(5),
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE student_lifestyle (
    student_id VARCHAR(20) PRIMARY KEY,
    study_hours_per_week DECIMAL(4,1),
    extracurricular_activities VARCHAR(5),
    internet_access_at_home VARCHAR(5),
    parent_education_level VARCHAR(50),
    family_income_level VARCHAR(20),
    stress_level INT,
    sleep_hours_per_night DECIMAL(3,1),
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
