#1a. Top 5 students including all departments 
#finds the top 5 score ranks using DENSE_RANK()
SELECT s.student_id,s.full_name,s.department,a.total_score,
       RANK() OVER (ORDER BY total_score DESC) AS overall_rank
FROM academic_performance a join students s 
on s.student_id=a.student_id limit 5;

#1b. Top 5 students per department
#finds the top 5 score ranks in each department using (CTE + DENCE_RANK)
with ranked as(
select s.student_id,s.full_name,s.department,a.total_score,
dense_rank()over(partition by s.department order by a.total_score desc)as dept_rank
from students s join academic_performance a
on s.student_id=a.student_id)
select*from ranked where dept_rank<=5
order by department,dept_rank; 

#2. Students academic status based on their own department's average
#It classifies every student as Below Average, Above Average, or Same as Average compared with their department average 
#(window function + subquery/derived table + CASE statement)

SELECT student_id,full_name,department,total_score,dept_avg,
CASE 
    when total_score < dept_avg then "Below Average"
    when total_score> dept_avg then "Above Average"
    else "Same as Average"
    end as Performance_status FROM
(SELECT s.student_id,s.full_name, s.department, a.total_score,
       ROUND(AVG(a.total_score) OVER (PARTITION BY s.department), 2) AS dept_avg
FROM students s
JOIN academic_performance a ON s.student_id = a.student_id) t;

#3. Find the highest and lowest score in each department
SELECT 
    s.department,
    MAX(a.total_score) AS highest_score,
    MIN(a.total_score) AS lowest_score
FROM students s
JOIN academic_performance a
    ON s.student_id = a.student_id
GROUP BY s.department;

#4. Score Gap Between Students Using LAG()
#Calculate the score gap between each student and the next higher-scoring student within the same department using LAG().
WITH ranked_scores AS (
    SELECT
        s.student_id,
        s.full_name,
        s.department,
        a.total_score,
        LAG(a.total_score) OVER (
            PARTITION BY s.department
            ORDER BY a.total_score DESC
        ) AS next_higher_score
    FROM students s
    JOIN academic_performance a
        ON s.student_id = a.student_id
)SELECT
    student_id,
    full_name,
    department,
    total_score,
    next_higher_score,
    ROUND(next_higher_score - total_score, 2) AS score_gap
FROM ranked_scores
ORDER BY department, total_score DESC;

#5. Stored Procedure – Get Lifestyle Details by Student ID
#Create a stored procedure that displays lifestyle details for a specific student using their student_id.
DELIMITER //
CREATE PROCEDURE get_student_lifestyle(IN p_student_id VARCHAR(10))
BEGIN
    SELECT *
    FROM student_lifestyle
    WHERE student_id = p_student_id;
END //
DELIMITER ;
call get_student_lifestyle('S1000')





